  page: Page,
  testInfo: TestInfo,
  routes: CaptureRoute[],
): Promise<void> {
  for (const route of routes) {
    await page.goto(route.path);
    await expect(
      page.getByRole("heading", { name: new RegExp(route.heading) }).first(),
    ).toBeVisible();
    await page.screenshot({
      path: testInfo.outputPath("screens", `${route.name}.png`),
      fullPage: true,
      animations: "disabled",
    });
  }
}

